<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { useRoute } from 'vue-router';
import { ArrowRight, CircleHelp, Download, ExternalLink, Monitor, Search, Smartphone, Zap } from 'lucide-vue-next';
import clients from '../data/clients.json';
import { t } from '../i18n';
import { usePanelContext } from '../composables/panelContext';
import { clientDownloadURL, clientPlatforms, detectClientPlatform, isGitHubReleaseDownload, platformDownloads, type Client } from '../lib/clientDownloads';
import PageHeading from '../components/PageHeading.vue';
import ClientBrand from '../components/member/ClientBrand.vue';
import '../styles/member-ui.css';
const route=useRoute(),{site,selectedSite}=usePanelContext();
const detected=typeof navigator==='undefined'?'':detectClientPlatform(navigator.userAgent,navigator.platform,navigator.maxTouchPoints);
const routePlatform=String(route.query.platform||'');
const platform=ref(clientPlatforms.some(value=>value===routePlatform)?routePlatform:detected),search=ref(''),selection=ref<Record<string,string>>({});
const relay=computed(()=>!selectedSite.value&&site.value.client_download_relay===true);
const visible=computed(()=>clients.filter(client=>(!platform.value||client.downloads.some(download=>download.platform===platform.value))&&(!search.value.trim()||[client.name,client.format,...client.protocols].some(value=>value.toLowerCase().includes(search.value.trim().toLowerCase())))));
const downloads=(client:Client)=>platformDownloads(client,platform.value);
const selected=(client:Client)=>{const value=selection.value[client.id];return value===undefined||value===''?undefined:client.downloads[Number(value)]};
const href=(client:Client)=>selected(client)?clientDownloadURL(client,Number(selection.value[client.id]),relay.value):'';
const viaRelay=(client:Client)=>relay.value&&!!selected(client)&&isGitHubReleaseDownload(selected(client)!.url);
watch(platform,()=>{for(const client of clients){const available=downloads(client),previous=selection.value[client.id];selection.value[client.id]=available.some(item=>String(item.index)===previous)?previous!:available.length===1?String(available[0]!.index):''}},{immediate:true});
</script>
<template>
  <section class="member-page clients-page">
    <PageHeading :title="t('客户端中心')" :description="t('选好设备，下载客户端，再导入你的订阅。')" eyebrow="CLIENTS"><template #actions><RouterLink class="member-link" to="/subscription?connect=1">{{t('已安装，前往连接')}}<ArrowRight :size="16"/></RouterLink></template></PageHeading>
    <div class="client-intro"><span class="intro-icon"><Download :size="22"/></span><div><h2>{{t('把服务带到你的设备')}}</h2><p>{{t('安装包按设备平台对应；不确定架构时，可展开下方说明。')}}</p></div><span v-if="relay" class="download-relay"><Zap :size="14"/>{{t('下载加速已启用')}}</span></div>
    <div class="client-filters"><div class="member-tabs platforms" role="group" :aria-label="t('选择操作系统')"><button :aria-pressed="!platform" @click="platform=''">{{t('全部设备')}}</button><button v-for="value in clientPlatforms" :key="value" :aria-pressed="platform===value" @click="platform=value"><component :is="value==='Android'||value==='iOS / iPadOS'?Smartphone:Monitor" :size="16"/>{{value}}</button></div><label class="member-search"><Search :size="16"/><input v-model="search" type="search" :placeholder="t('搜索客户端')" :aria-label="t('搜索客户端')"/></label></div>
    <div class="client-results"><p>{{platform||t('全部设备')}} · {{visible.length}} {{t('款客户端')}}<span v-if="platform&&platform===detected"> · {{t('已匹配当前设备，可随时切换')}}</span></p><details class="client-help"><summary><CircleHelp :size="16"/>{{t('如何选择安装包')}}</summary><p>{{t('Apple Silicon 选择 ARM64，Intel / AMD 电脑通常选择 x64；Android 请在设备信息中核对架构。直链为已核实版本，其他格式或新版请打开官方发布页。')}}</p></details></div>
    <div v-if="visible.length" class="client-grid">
      <article v-for="client in visible" :key="client.id" class="member-panel client-card">
        <header><ClientBrand :client="client" :size="52"/><div class="client-title"><h2>{{client.name}}</h2><p>{{client.version?'v'+client.version:t('商店分发')}}</p></div><span :class="['member-status',client.paid?'':'active']">{{client.paid?t('付费'):t('免费')}}</span></header>
        <div class="client-tags"><span v-for="value in [...new Set(client.downloads.map(item=>item.platform))]" :key="value">{{value}}</span></div>
        <p class="client-note">{{t(client.note)}}</p>
        <div class="client-install"><label :for="'client-package-'+client.id">{{t('选择安装包')}}</label><select :id="'client-package-'+client.id" v-model="selection[client.id]"><option v-if="downloads(client).length>1" value="" disabled>{{platform?t('选择设备架构'):t('选择设备与架构')}}</option><option v-for="item in downloads(client)" :key="item.index" :value="String(item.index)">{{item.platform}} · {{item.arch}}</option></select><a v-if="selected(client)" class="member-button primary download-button" :href="href(client)" target="_blank" rel="noopener noreferrer"><Download :size="17"/>{{selected(client)!.arch==='App Store'?t('在 App Store 获取'):selected(client)!.arch==='F-Droid'?t('在 F-Droid 获取'):t('下载安装包')}}<ExternalLink :size="15"/></a><button v-else class="primary download-button" disabled><Download :size="17"/>{{t('请先选择安装包')}}</button><div class="download-source"><span><Zap v-if="viaRelay(client)" :size="13"/>{{viaRelay(client)?t('通过本站加速下载'):t('官方来源')}}</span><a v-if="viaRelay(client)" :href="selected(client)!.url" target="_blank" rel="noopener noreferrer">{{t('切换官方下载')}}<ExternalLink :size="12"/></a></div></div>
        <RouterLink class="client-connect" :to="{path:'/subscription',query:{connect:'1',client:client.id,...(platform?{platform}:selected(client)?{platform:selected(client)!.platform}:{})}}">{{t('已安装，开始配置')}}<ArrowRight :size="16"/></RouterLink>
        <footer><a :href="client.source" target="_blank" rel="noopener noreferrer">{{t('官方发布页')}}<ExternalLink :size="13"/></a><details class="client-compatibility"><summary>{{t('兼容信息')}}</summary><p>{{client.format}} · {{client.protocols.join(' / ')}}</p><a :href="client.icon_source" target="_blank" rel="noopener noreferrer">{{client.icon_kind==='official'?t('官方图标来源'):t('文字标记说明')}}<ExternalLink :size="12"/></a></details></footer>
      </article>
    </div>
    <div v-else class="member-empty"><Search :size="30"/><h2>{{t('没有匹配的客户端')}}</h2><p>{{t('试试其他名称或切换操作系统。')}}</p><button @click="search='';platform=''">{{t('清除筛选')}}</button></div>
    <p class="client-attribution">{{t('客户端由各自开发者维护。')}} <a href="/clients/ATTRIBUTION.md" target="_blank" rel="noopener noreferrer">{{t('图标来源与许可')}}</a></p>
  </section>
</template>
<style scoped>
