color:var(--secondary);font-size:12px;line-height:1.6;padding:4px 8px;background:var(--surface-raised);border-radius:5px}.client-note{font-size:13px;line-height:1.8;color:var(--secondary);margin:0;overflow-wrap:anywhere}.client-install{display:flex;flex-direction:column;gap:9px;margin-top:auto;padding-top:3px}.client-install label{font-size:13px;font-weight:550}.client-install select{width:100%;min-width:0}.download-button{display:flex;gap:8px;justify-content:center;min-height:46px}.download-source{display:flex;gap:8px;justify-content:space-between;align-items:center;font-size:12px;min-height:28px;color:var(--secondary);flex-wrap:wrap}.download-source>span,.download-source>a{display:inline-flex;gap:5px;align-items:center}.download-source>a{color:var(--accent-text);min-height:32px;text-decoration:none}.client-connect{display:flex;align-items:center;justify-content:center;gap:8px;min-height:44px;font-size:13px;color:var(--accent-text);text-decoration:none;border:1px solid var(--border);border-radius:8px;margin-top:-3px}.client-connect:hover{background:var(--accent-soft)}.client-card footer{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;border-top:1px solid var(--border);padding-top:9px;font-size:12px}.client-card footer a{display:inline-flex;gap:5px;align-items:center;min-height:44px;color:var(--secondary);text-decoration:none}.client-compatibility{text-align:right}.client-compatibility summary{min-height:44px;align-content:center;cursor:pointer;color:var(--secondary)}.client-compatibility p{font-size:12px;color:var(--secondary);line-height:1.7;margin:4px 0}.client-attribution{font-size:12px;color:var(--secondary);text-align:center;line-height:1.8;margin:0}.client-attribution a{color:var(--accent-text);min-height:44px;display:inline-flex;align-items:center}@media(max-width:900px){.client-filters .platforms{flex-basis:100%}.client-filters .member-search{max-width:none}.client-results{flex-direction:column;gap:0}.client-help{max-width:none}.client-results>p{margin:0}.client-results{margin-top:-4px}}@media(max-width:600px){.client-intro{padding:18px;gap:12px;flex-wrap:wrap}.client-intro>div{flex:1;min-width:0}.client-intro h2{font-size:16px}.download-relay{margin-left:58px;padding:5px 9px}.platforms button{flex:1 0 29%;font-size:12px}.client-grid{grid-template-columns:1fr}.client-install select{font-size:16px}.download-source>a{min-height:44px}.client-card{gap:16px}}
